import numpy as np, itertools, sys
# ---------- GF(2^18) ----------
D=18
# find primitive polynomial of degree 18 over GF(2)
def gf_mul(a,b,POLY,D):
    r=0
    while b:
        if b&1: r^=a
        b>>=1; a<<=1
        if a>>D: a^=POLY
    return r
def gf_pow(a,e,POLY,D):
    r=1
    while e:
        if e&1: r=gf_mul(r,a,POLY,D)
        a=gf_mul(a,a,POLY,D); e>>=1
    return r
def find_prim(D):
    N=(1<<D)-1
    fac=[p for p in [3,7,19,73] ]
    for POLY in range((1<<D)+1,(1<<(D+1)),2):
        if gf_pow(2,N,POLY,D)!=1: continue
        if all(gf_pow(2,N//p,POLY,D)!=1 for p in fac): return POLY
POLY=find_prim(D)
N=(1<<D)-1
M=37
# primitive 37th root of unity in F(2^36)? t_j live in F(2^18); we need zeta in F(2^36).
# Simpler: compute t_j via the minimal polynomial of t=zeta+1/zeta over GF(2): work in F(2^18) directly.
# Minimal polynomial of t_1: product over j in (Z/37)*/±1 of (X - t_j). Compute via Chebyshev/Dickson: x^37-1 = (x-1) * prod ... Use: Phi_37(x)/x^18 = Psi(t) with Psi of degree 18 in t.
# Build Psi: Phi_37(x) = 1+x+...+x^36. x^-18 Phi = sum_{k=-18}^{18} x^k = 1 + sum_{k=1}^{18} (x^k+x^-k) = 1 + sum T_k(t), T_k(t)=x^k+x^-k as poly in t.
def poly_mul(p,q):  # polys over GF(2) as int bitmasks
    r=0
    while q:
        if q&1: r^=p
        q>>=1; p<<=1
    return r
def poly_mod(p,m):
    dm=m.bit_length()-1
    while p.bit_length()-1>=dm:
        p^=m<<(p.bit_length()-1-dm)
    return p
# T_0=2=0, T_1=t, T_{k+1}=t*T_k - T_{k-1} = t*T_k + T_{k-1}
T=[0,2]  # bitmask polys in t: T0=0, T1=t (=0b10)
for k in range(2,40): T.append(poly_mul(2,T[-1])^T[-2])
Psi=1
for k in range(1,19): Psi^=T[k]
assert Psi.bit_length()-1==18
# find a root of Psi in F(2^18): brute force
def eval_poly(p,a,POLY,D):
    r=0; i=p.bit_length()-1
    while i>=0:
        r=gf_mul(r,a,POLY,D)
        if (p>>i)&1: r^=1
        i-=1
    return r
def find_root():
    for a in range(2,1<<D):
        if eval_poly(Psi,a,POLY,D)==0: return a
t1=find_root()
# t_j = T_j(t1)
tj=[eval_poly(T[j],t1,POLY,D) if j>0 else 0 for j in range(M)]
for j in range(M): assert tj[j]==tj[(M-j)%M]
# check Frobenius: t_{2j} = t_j^2
for j in range(M): assert gf_mul(tj[j],tj[j],POLY,D)==tj[(2*j)%M]
# ---------- group ring F2[x,y]/(x^37-1,y^37-1) as 37x37 arrays ----------
def orbit(a,b):
    S=set()
    for (u,v) in [(a,b),(b,a)]:
        for su in (1,-1):
            for sv in (1,-1): S.add((su*u,sv*v))
    return S
ORB=[(a,b) for a in range(5) for b in range(a+1)]
ORB=sorted(ORB,key=lambda ab:(ab[0],ab[1]))  # (0,0),(1,0),(1,1),(2,0),(2,1),(2,2),(3,0),...
def rule(n):
    A=np.zeros((M,M),dtype=np.uint8)
    for i,(a,b) in enumerate(ORB):
        if (n>>i)&1:
            for (u,v) in orbit(a,b): A[u%M,v%M]^=1
    return A
def gmul(A,B):
    # cyclic convolution mod 2
    C=np.zeros((M,M),dtype=np.int64)
    for i,j in zip(*np.nonzero(A)):
        C+=np.roll(np.roll(B,i,axis=0),j,axis=1)
    return (C%2).astype(np.uint8)
def dil(A,d):  # (x,y)->(x^d,y^d)
    B=np.zeros_like(A)
    for i,j in zip(*np.nonzero(A)): B[(d*i)%M,(d*j)%M]^=1
    return B
def eig(A):
    # lambda(j,k) = sum_{(u,v) in supp} zeta^{ju+kv}; use symmetric structure? general: need zeta. Use t-values via symmetric rules only.
    raise NotImplementedError
def eig_sym(A):
    # for symmetric A (invariant under (u,v)->(-u,-v) at least): lambda(j,k)= sum over pairs ... we use: sum_{(u,v)} zeta^{ju+kv}. Pair (u,v) with (-u,-v): gives t_{ju+kv}.  Requires A centrally symmetric.
    L=np.zeros((M,M),dtype=np.int64)
    pts=list(zip(*np.nonzero(A)))
    for j in range(M):
        for k in range(M):
            s=0
            for (u,v) in pts:
                w=(j*u+k*v)%M
                if w==0: s^=1   # pair (u,v),(-u,-v) both give 1 -> cancel; handle below
                # we count each point: zeta^w + zeta^{-w} = t_w, but each pair counted twice -> use half
            L[j,k]=s
    return L
def eig_sym2(A):
    # proper: for centrally symmetric A: lambda(j,k) = [ (0,0) in A ] + sum over pairs {(u,v),(-u,-v)} t_{ju+kv}
    pts=[(u,v) for (u,v) in zip(*np.nonzero(A))]
    pairs=[]
    seen=set()
    for (u,v) in pts:
        if (u,v) in seen: continue
        w=((-u)%M,(-v)%M)
        if w==(u,v): continue
        assert A[w]==1, "not centrally symmetric"
        seen.add((u,v)); seen.add(w); pairs.append((u,v))
    L=np.zeros((M,M),dtype=np.int64)
    c0=int(A[0,0])
    for j in range(M):
        for k in range(M):
            s=c0
            for (u,v) in pairs: s^=tj[(j*u+k*v)%M]
            L[j,k]=s
    return L
def order(a):
    if a==0: return 0
    o=N
    for p in [3,3,3,7,19,73]:
        if gf_pow(a,o//p,POLY,D)==1: o//=p
    return o
def confinement(L):
    from math import gcd, lcm
    l=1
    for v in L.flatten():
        if v: l=lcm(l,order(int(v)))
    return l

